{
  "investigate": [
    {
      "tool": "sql",
      "query": "SELECT service, used_mb, quota_mb FROM storage WHERE service = 'sync-job'",
      "why": "Confirm sync-job disk usage is above quota and check if it is the root cause of its own errors and worker dependencies."
    }
  ],
  "hypotheses": [
    {
      "service": "sync-job",
      "kind": "resource_exhaustion",
      "mechanism": "Sync-job exhausted disk quota (1260.5MB used vs 1000MB quota), causing ledger export write failures and sync errors.",
      "supporting": ["E16", "E33"],
      "refuting": [],
      "explains": ["E3", "E6"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "sync-job"}}
      ]
    },
    {
      "service": "worker",
      "kind": "resource_exhaustion",
      "mechanism": "Worker exhausted disk quota earlier (now resolved per E33), but residual effects persist with dead letters and processing halts.",
      "supporting": ["E14", "E15", "E2", "E4", "E7", "E8", "E32"],
      "refuting": ["E33"],
      "explains": ["M2_error_burst", "M3_dead_letters"],
      "repair_plan": [
        {"action": "restart_service", "params": {"service": "worker"}}
      ]
    }
  ],
  "summary": "Sync-job disk exhaustion is causing sync failures, and worker disk exhaustion (now resolved) caused residual dead letters."
}
